const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, BorderStyle
} = require("docx");

const doc = new Document({
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 } } // US Letter
    },
    children: [
      new Paragraph({
        text: "Sales Memo — July 2026",
        heading: HeadingLevel.HEADING_1,
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "To: ", bold: true }),
          new TextRun("Shop Owner"),
        ],
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "Date: ", bold: true }),
          new TextRun("September 27, 2026"),
        ],
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: "999999", space: 4 } },
        spacing: { after: 200 },
      }),
      new Paragraph({
        children: [
          new TextRun(
            "Backpacks drove the month: just 15 units (11 orders) brought in "
          ),
          new TextRun({ text: "฿6,750 — about 64% of total revenue", bold: true }),
          new TextRun(
            " (฿10,497), even though gel pens and sticky notes each sold more units. Highlighter sets were the strong #2 (15% of revenue from just 5 orders), suggesting good margin-per-sale on both items."
          ),
        ],
        spacing: { after: 150 },
      }),
      new Paragraph({
        children: [
          new TextRun(
            "Gel pens, notebooks, and sticky notes sold in high volume but contributed little revenue each — useful for footfall, not profit. One backpack sale (July 5) is missing its quantity and price and was excluded from totals; worth checking that record."
          ),
        ],
        spacing: { after: 150 },
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "Bottom line: ", bold: true }),
          new TextRun(
            "consider stocking more backpacks and highlighter sets, and bundling low-ticket items with them to lift basket size."
          ),
        ],
      }),
    ],
  }],
});

Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync("/home/claude/agent-case/output/sales_memo.docx", buf);
  console.log("saved");
});
EOF
